{"chunk_id":"7b2cd1","wall_time_seconds":0.4572824,"exit_code":0,"original_token_count":3003,"output":""""Generate bounded fixed Firefly cues; no board access, retries or secret output."""
from pathlib import Path
import importlib.util,json,re,hashlib,time,urllib.request,ssl,concurrent.futures
R=Path(__file__).resolve().parents[3]; D=Path(__file__).resolve().parent
O=D/'firefly-fixed-prompts-20261028-r3'; O.mkdir(exist_ok=False)
spec=importlib.util.spec_from_file_location('prompt_assets',R/'tools/generate_private_prompt_assets.py'); gen=importlib.util.module_from_spec(spec);spec.loader.exec_module(gen)
config=(R/'app/k7boot/private/aliyun_boot_config.inc').read_text(encoding='utf8')
key=gen.field(config,'vv_private_aliyun_key'); model=gen.field(config,'vv_private_aliyun_tts_model')
assert model=='qwen-audio-3.0-tts-flash'
manifest=json.loads((R/'private/firefly-materials-20261023-r1/clone-reference-client-r2/reference-manifest.json').read_text(encoding='utf8'))
host=manifest['endpoint_host']; assert re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9-]{0,63}\.cn-beijing\.maas\.aliyuncs\.com',host)
voice='qwen-audio-3.0-tts-flash-fireflycn-ec57cdbd4ff849029347050720cf97d4'
prompts=gen.texts(); assert len(prompts)==12
def one(pair):
 i,text=pair; began=time.monotonic()
 body=json.dumps({'model':model,'input':{'text':text,'voice':voice,'format':'pcm','sample_rate':16000}},ensure_ascii=False).encode()
 req=urllib.request.Request('https://'+host+'/api/v1/services/audio/tts/SpeechSynthesizer',data=body,headers={'Authorization':'Bearer '+key,'Content-Type':'application/json','X-DashScope-SSE':'enable'})
 try:
  old=D/'firefly-fixed-prompts-20261028-r2'/('response-%02d.sse'%i)
  if old.exists(): wire=old.read_bytes(); reused=True
  else:
   with urllib.request.urlopen(req,timeout=40,context=ssl.create_default_context()) as res:
    if res.status!=200 or not res.headers.get('Content-Type','').startswith('text/event-stream'): raise ValueError('http_or_mime')
    wire=res.read(2*1024*1024+1); reused=False
  assert len(wire)<=2*1024*1024
  (O/('response-%02d.sse'%i)).write_bytes(wire)
  # SSE events may contain one pretty-printed JSON document over many data lines.
  events=[]; data=[]
  for line in wire.splitlines()+[b'']:
   if not line:
    if data: events.append(b'data:'+b'\n'.join(data)); data=[]
   elif line.startswith(b'data:'): data.append(line[5:].lstrip(b' '))
  pcm=gen.decode_sse(events)
  if not reused: time.sleep(.4)
  p=O/('prompt-%02d.pcm'%i); p.write_bytes(pcm)
  item={'index':i,'text':text,'file':p.name,'bytes':len(pcm),'sha256':gen.sha(pcm),'duration_ms':len(pcm)/32,'elapsed_ms':round((time.monotonic()-began)*1000),'terminal_validated':True}
  (O/('prompt-%02d.json'%i)).write_text(json.dumps(item,ensure_ascii=False,indent=2),encoding='utf8')
  print(json.dumps({'completed_index':i,'bytes':len(pcm),'elapsed_ms':item['elapsed_ms']}),flush=True)
  return item,pcm
 except Exception as e:
  (O/('failure-%02d.json'%i)).write_text(json.dumps({'index':i,'exception':type(e).__name__,'automatic_retry':False}),encoding='utf8')
  raise RuntimeError('Fixed cue generation failed; provider response withheld') from None
try:
 with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool: results=list(pool.map(one,enumerate(prompts)))
 total=sum(len(pcm) for _,pcm in results); assert total<=gen.MAX_TOTAL
 inc=gen.render([(item['text'],pcm) for item,pcm in results],model,voice).replace('vv_private_prompt','vv_firefly_prompt').encode()
 (O/'vv_firefly_prompt_assets.inc').write_bytes(inc)
 report={'passed':True,'model':model,'voice':voice,'sample_rate':16000,'channels':1,'format':'pcm_s16le','total_pcm_bytes':total,'entries':[i for i,_ in results],'include_sha256':gen.sha(inc),'automatic_retry':False,'board_accessed':False,'credentials_stored':False}
 (O/'manifest.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
