--- a/app/k7radio/k7radio_main.c
+++ b/app/k7radio/k7radio_main.c
@@ -795,6 +795,71 @@
   nxmutex_unlock(&g_wifi_state);
 }

+#if defined(K7_RADIO_FIRSTFAULT_DIAG) && K7_RADIO_FIRSTFAULT_DIAG
+/* Private diagnostics only. Bus fields are copied under the existing bus
+ * mutex, published once, and never refreshed by a status read. */
+struct radio_firstfault_diag
+{
+  bool bus_ready, rx_ready, dw_faulted;
+  unsigned int opcode;
+  uint32_t argument, raw, status, card_bytes;
+  size_t request_bytes, host_bytes;
+  int bus_result, cleanup, rx_result;
+  uint64_t receive_elapsed_us;
+};
+static struct radio_firstfault_diag g_radio_firstfault;
+static uint64_t g_radio_receive_start_us;
+static void radio_firstfault_bus(unsigned int opcode, uint32_t argument,
+                                 size_t request_bytes, int result)
+{
+  if (!g_bt_host_mode || result >= 0 ||
+      __atomic_load_n(&g_radio_firstfault.bus_ready, __ATOMIC_ACQUIRE)) return;
+  g_radio_firstfault.opcode = opcode;
+  g_radio_firstfault.argument = argument;
+  g_radio_firstfault.request_bytes = request_bytes;
+  g_radio_firstfault.bus_result = result;
+  g_radio_firstfault.dw_faulted = g_fw_host.dw.faulted;
+  g_radio_firstfault.raw = g_fw_host.dw.last_raw;
+  g_radio_firstfault.status = g_fw_host.dw.last_status;
+  g_radio_firstfault.host_bytes = g_fw_host.dw.host_bytes;
+  g_radio_firstfault.card_bytes = g_fw_host.dw.card_bytes;
+  g_radio_firstfault.cleanup = g_fw_host.dw.cleanup_error;
+  __atomic_store_n(&g_radio_firstfault.bus_ready, true, __ATOMIC_RELEASE);
+}
+static bool radio_firstfault_rx(int result)
+{
+  if (result >= 0 ||
+      __atomic_load_n(&g_radio_firstfault.rx_ready, __ATOMIC_ACQUIRE)) return false;
+  uint64_t end = now_us();
+  g_radio_firstfault.rx_result = result;
+  g_radio_firstfault.receive_elapsed_us = end - g_radio_receive_start_us;
+  __atomic_store_n(&g_radio_firstfault.rx_ready, true, __ATOMIC_RELEASE);
+  return true;
+}
+static void radio_firstfault_print(void)
+{
+  bool bus = __atomic_load_n(&g_radio_firstfault.bus_ready, __ATOMIC_ACQUIRE);
+  bool rx = __atomic_load_n(&g_radio_firstfault.rx_ready, __ATOMIC_ACQUIRE);
+  if (!bus && !rx) return;
+  printf("RADIO FIRSTFAULT rx_valid=%u rx_rc=%d receive_us=%" PRIu64
+         " bus_valid=%u op=%u arg=%08" PRIx32 " request=%zu bus_rc=%d"
+         " dw_fault=%u raw=%08" PRIx32 " status=%08" PRIx32
+         " host=%zu card=%" PRIu32 " cleanup=%d cached=1\n",
+         rx, rx ? g_radio_firstfault.rx_result : 0,
+         rx ? g_radio_firstfault.receive_elapsed_us : UINT64_C(0),
+         bus, bus ? g_radio_firstfault.opcode : 0,
+         bus ? g_radio_firstfault.argument : 0,
+         bus ? g_radio_firstfault.request_bytes : 0,
+         bus ? g_radio_firstfault.bus_result : 0,
+         bus ? g_radio_firstfault.dw_faulted : false,
+         bus ? g_radio_firstfault.raw : 0,
+         bus ? g_radio_firstfault.status : 0,
+         bus ? g_radio_firstfault.host_bytes : 0,
+         bus ? g_radio_firstfault.card_bytes : 0,
+         bus ? g_radio_firstfault.cleanup : 0);
+}
+#endif
